"use strict";(globalThis.webpackChunkpolymesh_developer_documentation=globalThis.webpackChunkpolymesh_developer_documentation||[]).push([[64485],{27393(e){e.exports=JSON.parse('{"tag":{"label":"evm","permalink":"/polymesh-documentation-site/tags/evm","allTagsPath":"/polymesh-documentation-site/tags","count":13,"items":[{"id":"developer-resources/smart-contracts/evm-address-mapping","title":"Address Mapping","description":"How Polymesh 32-byte accounts and 20-byte EVM addresses map onto each other, why the mapping is one-way in one direction, and why an account must call map_account before receiving funds at its EVM address.","permalink":"/polymesh-documentation-site/development/smart-contracts/address-mapping"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-eth-wallets","title":"ETH Wallets Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 supports EVM-keyed accounts as subsidy beneficiaries and MultiSig signers, makes authorization acceptance fee-free for them, and restricts transaction tipping to the Governance Committee.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/eth-wallets"},{"id":"developer-resources/tooling/sdk/sdk-evm-wallets","title":"EVM Wallets","description":"Sign and submit Polymesh transactions with an EVM key - MetaMask, WalletConnect, viem and ethers - using the Polymesh SDK\'s EVM signing manager.","permalink":"/polymesh-documentation-site/development/tooling/sdk/evm-wallets"},{"id":"developer-resources/smart-contracts/precompiles/precompile-fungible-asset","title":"Fungible Asset Precompile (ERC-20)","description":"Use any Polymesh fungible asset as an ERC-20 token from Solidity and Ethereum tooling, with parts of ERC-3643 and ERC-7943 - address derivation, the full method reference, events, revert reasons, and the limits to design around.","permalink":"/polymesh-documentation-site/development/smart-contracts/precompiles/fungible-asset"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-fungible-asset-precompile","title":"Fungible Asset Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1 exposes every native fungible asset as an ERC-20 token through a pallet-revive precompile; v8.1.1 completes the ERC-3643 and ERC-7943 surface with pausing, agent checks, partial freezing and recipient-directed forced transfers.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/fungible-asset-precompile"},{"id":"developer-resources/tooling/local-environment","title":"Local Development Environment","description":"Run a complete Polymesh stack locally with Docker Compose, including the node, indexer, REST APIs, Vault, and optional Ethereum JSON-RPC and Blockscout explorer","permalink":"/polymesh-documentation-site/development/tooling/local-setup"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-nft-precompile","title":"NFT Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 exposes every NFT collection as an ERC-721 token through a pallet-revive precompile, with ERC-721Metadata token URIs, ERC-165 introspection and ERC-7943 transfer checks.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/nft-precompile"},{"id":"developer-resources/smart-contracts/precompiles/precompile-non-fungible-asset","title":"Non-Fungible Asset Precompile (ERC-721)","description":"Use any Polymesh NFT collection as an ERC-721 token from Solidity and Ethereum tooling - address derivation, the full method reference, token URIs, approvals, events, revert reasons, and the deviations to design around.","permalink":"/polymesh-documentation-site/development/smart-contracts/precompiles/non-fungible-asset"},{"id":"developer-resources/smart-contracts/precompiles/precompile-polymesh-runtime","title":"Polymesh Runtime Precompile","description":"Call general-purpose Polymesh extrinsics from Solidity - create assets, register tickers, onboard identities and authorize external agents through a single fixed-address precompile.","permalink":"/polymesh-documentation-site/development/smart-contracts/precompiles/polymesh-runtime"},{"id":"developer-resources/changelogs/v8.0-to-v8.1.2/v8.0-to-v8.1.2-runtime-precompile","title":"Polymesh Runtime Precompile Changelog - v8.0 to v8.1.2","description":"Polymesh chain v8.1.1 adds a general-purpose precompile exposing asset creation, ticker registration, DID onboarding and external agent authorization to EVM contracts.","permalink":"/polymesh-documentation-site/development/changelogs/v8.0-to-v8.1.2/runtime-precompile"},{"id":"developer-resources/smart-contracts/precompiles/precompiles-index","title":"Precompiles","description":"How Polymesh exposes native chain functionality to smart contracts through pallet-revive precompiles - the address scheme, shared call semantics, and the list of available precompiles.","permalink":"/polymesh-documentation-site/development/smart-contracts/precompiles"},{"id":"developer-resources/smart-contracts/runtime-calls-from-evm","title":"Runtime Calls from an EVM Wallet","description":"Submit native Polymesh extrinsics from an EVM key such as a MetaMask account, by sending a transaction to the reserved runtime-pallets address - no smart contract and no precompile involved.","permalink":"/polymesh-documentation-site/development/smart-contracts/runtime-calls"},{"id":"developer-resources/changelogs/v7.4-to-v8.0/v7.4-to-v8.0-smart-contracts-evm","title":"Smart Contracts Changelog - v7.4 to v8.0","description":"Polymesh chain v8 adds pallet-revive, a dual-VM (PolkaVM + EVM) smart contract engine, as the only smart contract pallet on Polymesh.","permalink":"/polymesh-documentation-site/development/changelogs/v7.4-to-v8.0/smart-contracts-evm"}],"unlisted":false}}')}}]);